import{_ as h,o as t,c as i,a2 as g}from"./chunks/framework.CqpfiAoK.js";const v=JSON.parse('{"title":"Luật Bảo vệ Người tiêu dùng","description":"","frontmatter":{},"headers":[],"relativePath":"vi/42-消费者保护法.md","filePath":"vi/42-消费者保护法.md"}'),c={name:"vi/42-消费者保护法.md"};function a(u,n,d,o,l,r){return t(),i("div",null,[...n[0]||(n[0]=[g('<h1 id="luat-bao-ve-nguoi-tieu-dung" tabindex="-1">Luật Bảo vệ Người tiêu dùng <a class="header-anchor" href="#luat-bao-ve-nguoi-tieu-dung" aria-label="Permalink to &quot;Luật Bảo vệ Người tiêu dùng&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>42</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Quyền người tiêu dùng, giao dịch công bằng, chống lừa đảo, trách nhiệm sản phẩm, thị trường cộng sinh</td></tr></tbody></table><h2 id="_1-muc-đich-lap-phap-va-pham-vi-ap-dung" tabindex="-1">1. Mục đích lập pháp và phạm vi áp dụng <a class="header-anchor" href="#_1-muc-đich-lap-phap-va-pham-vi-ap-dung" aria-label="Permalink to &quot;1. Mục đích lập pháp và phạm vi áp dụng&quot;">​</a></h2><p>《Luật Bảo vệ Người tiêu dùng》 là một trong những luật pháp cốt lõi trong hệ thống pháp luật của văn minh cộng sinh neo, cùng với 《Luật Lao động Cộng sinh》 cấu thành hai trụ cột của đời sống kinh tế. Luật này nhằm bảo vệ quyền lợi hợp pháp của tất cả người tiêu dùng bên trong Hengyuanzhou, quy phạm hóa hành vi giao dịch thị trường, duy trì trật tự thị trường công bằng, trung thực, cộng sinh, và ngăn chặn sự xâm phạm quyền lợi của mọi sự sống do hành vi thương mại kiểu cướp đoạt.</p><p>Luật này áp dụng cho tất cả người tiêu dùng bên trong Hengyuanzhou mua, sử dụng hàng hóa hoặc tiếp nhận dịch vụ để đáp ứng nhu cầu sống cá nhân hoặc gia đình, cũng như các nhà kinh doanh cung cấp hàng hóa hoặc dịch vụ cho người tiêu dùng. Giao dịch xuyên位面 cũng áp dụng luật này, nhưng có thể ban hành quy định chi tiết thi hành theo sự khác biệt của位面.</p><h2 id="_2-quyen-co-ban-cua-nguoi-tieu-dung" tabindex="-1">2. Quyền cơ bản của người tiêu dùng <a class="header-anchor" href="#_2-quyen-co-ban-cua-nguoi-tieu-dung" aria-label="Permalink to &quot;2. Quyền cơ bản của người tiêu dùng&quot;">​</a></h2><p>Luật này thiết lập người tiêu dùng được hưởng chín quyền cơ bản sau:</p><table tabindex="0"><thead><tr><th>Quyền</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Quyền đảm bảo an toàn</td><td>Người tiêu dùng khi mua, sử dụng hàng hóa và tiếp nhận dịch vụ được hưởng quyền an toàn cá nhân, tài sản không bị tổn hại</td></tr><tr><td>Quyền biết sự thật</td><td>Người tiêu dùng có quyền biết tình hình thực tế của hàng hóa mua, sử dụng hoặc dịch vụ tiếp nhận, bao gồm thành phần, công hiệu, rủi ro, v.v.</td></tr><tr><td>Quyền lựa chọn tự chủ</td><td>Người tiêu dùng có quyền tự chủ lựa chọn hàng hóa hoặc dịch vụ, có quyền so sánh, nhận diện và lựa chọn, từ chối giao dịch cưỡng bức</td></tr><tr><td>Quyền giao dịch công bằng</td><td>Người tiêu dùng có quyền được các điều kiện giao dịch công bằng như đảm bảo chất lượng, giá cả hợp lý, đo lường chính xác, v.v.</td></tr><tr><td>Quyền đòi bồi thường theo pháp luật</td><td>Người tiêu dùng khi bị tổn hại cá nhân, tài sản do mua, sử dụng hàng hóa hoặc tiếp nhận dịch vụ được hưởng quyền được bồi thường theo pháp luật</td></tr><tr><td>Quyền lập hội bảo vệ quyền</td><td>Người tiêu dùng có quyền thành lập hoặc tham gia tổ chức người tiêu dùng theo pháp luật, bảo vệ quyền lợi hợp pháp của mình</td></tr><tr><td>Quyền được kiến thức</td><td>Người tiêu dùng có quyền được kiến thức và thông tin liên quan đến tiêu dùng và bảo vệ quyền lợi người tiêu dùng</td></tr><tr><td>Quyền được tôn trọng</td><td>Người tiêu dùng khi mua, sử dụng hàng hóa và tiếp nhận dịch vụ được hưởng quyền phẩm giá nhân cách, phong tục tập quán dân tộc được tôn trọng</td></tr><tr><td>Quyền giám sát</td><td>Người tiêu dùng có quyền giám sát hàng hóa và dịch vụ cũng như công tác bảo vệ quyền lợi người tiêu dùng, đưa ra phê bình và kiến nghị</td></tr></tbody></table><h2 id="_3-nghia-vu-cua-nha-kinh-doanh" tabindex="-1">3. Nghĩa vụ của nhà kinh doanh <a class="header-anchor" href="#_3-nghia-vu-cua-nha-kinh-doanh" aria-label="Permalink to &quot;3. Nghĩa vụ của nhà kinh doanh&quot;">​</a></h2><p>Nhà kinh doanh khi cung cấp hàng hóa hoặc dịch vụ cho người tiêu dùng phải thực hiện các nghĩa vụ sau:</p><ol><li><strong>Nghĩa vụ kinh doanh theo pháp luật</strong>: Nhà kinh doanh phải tuân thủ Hiến pháp và pháp luật, và hoạt động kinh doanh trong phạm vi kinh doanh đã được phê duyệt.</li><li><strong>Nghĩa vụ đảm bảo an toàn</strong>: Nhà kinh doanh phải đảm bảo hàng hóa hoặc dịch vụ cung cấp đáp ứng yêu cầu đảm bảo an toàn cá nhân, tài sản, và phải đưa ra giải thích thực tế và cảnh báo rõ ràng đối với hàng hóa và dịch vụ có thể gây nguy hiểm cho an toàn.</li><li><strong>Nghĩa vụ thông tin trung thực</strong>: Nhà kinh doanh phải cung cấp cho người tiêu dùng thông tin trung thực về hàng hóa hoặc dịch vụ, và không được quảng cáo giả mạo hoặc gây hiểu lầm. Hàng hóa và dịch vụ loại tu luyện phải ghi rõ ranh giới công hiệu và rủi ro tiềm ẩn một cách trung thực.</li><li><strong>Nghĩa vụ đảm bảo chất lượng</strong>: Nhà kinh doanh phải đảm bảo trong điều kiện sử dụng bình thường hàng hóa hoặc tiếp nhận dịch vụ, hàng hóa hoặc dịch vụ cung cấp có chất lượng, hiệu năng, công dụng và thời hạn hiệu lực mà nó nên có.</li><li><strong>Nghĩa vụ giao dịch công bằng</strong>: Nhà kinh doanh không được thông qua điều khoản định dạng, thông báo, tuyên bố, biển hiệu cửa hàng, v.v. đưa ra các quy định không công bằng, không hợp lý đối với người tiêu dùng như loại trừ hoặc hạn chế quyền người tiêu dùng, giảm hoặc miễn trách nhiệm nhà kinh doanh, tăng nặng trách nhiệm người tiêu dùng, v.v.</li><li><strong>Nghĩa vụ dịch vụ sau bán hàng</strong>: Nhà kinh doanh phải theo quy định của nhà nước hoặc thỏa thuận với người tiêu dùng, chịu trách nhiệm sửa chữa, thay thế, trả hàng và các trách nhiệm dịch vụ sau bán hàng khác.</li><li><strong>Nghĩa vụ bảo vệ quyền riêng tư</strong>: Nhà kinh doanh phải bảo vệ thông tin cá nhân và dữ liệu ý thức của người tiêu dùng, và không được thu thập, sử dụng hoặc tiết lộ mà không có sự đồng ý của người tiêu dùng.</li></ol><h2 id="_4-giai-quyet-tranh-chap-va-trach-nhiem-phap-ly" tabindex="-1">4. Giải quyết tranh chấp và trách nhiệm pháp lý <a class="header-anchor" href="#_4-giai-quyet-tranh-chap-va-trach-nhiem-phap-ly" aria-label="Permalink to &quot;4. Giải quyết tranh chấp và trách nhiệm pháp lý&quot;">​</a></h2><p>Khi có tranh chấp quyền lợi người tiêu dùng giữa người tiêu dùng và nhà kinh doanh, có thể giải quyết thông qua các con đường sau:</p><ul><li>Đàm phán và hòa giải với nhà kinh doanh</li><li>Yêu cầu tổ chức người tiêu dùng hòa giải</li><li>Khiếu nại với cơ quan hành chính có liên quan</li><li>Đề nghị cơ quan trọng tài trọng tài theo thỏa thuận trọng tài đã达成 với nhà kinh doanh</li><li>Khởi kiện lên Tòa án Cộng sinh</li></ul><p>Nhà kinh doanh vi phạm quy định của luật này, xâm phạm quyền lợi hợp pháp của người tiêu dùng, phải chịu trách nhiệm sau:</p><table tabindex="0"><thead><tr><th>Hành vi vi phạm pháp luật</th><th>Trách nhiệm pháp lý</th></tr></thead><tbody><tr><td>Cung cấp hàng hóa hoặc dịch vụ khuyết tật gây thiệt hại</td><td>Chịu trách nhiệm bồi thường, bao gồm chi phí y tế, bồi thường thiệt hại do nghỉ việc, bồi thường thương tật, v.v.</td></tr><tr><td>Hành vi lừa đảo</td><td>Tăng bồi thường theo yêu cầu của người tiêu dùng, số tiền là ba lần giá hàng hóa người tiêu dùng mua hoặc chi phí dịch vụ tiếp nhận</td></tr><tr><td>Quảng cáo giả mạo</td><td>Ra lệnh chấm dứt hành vi vi phạm pháp luật, loại bỏ ảnh hưởng, phạt tiền</td></tr><tr><td>Giao dịch cưỡng bức</td><td>Ra lệnh khắc phục, hoàn trả chi phí không hợp lý, phạt tiền</td></tr><tr><td>Xâm phạm quyền riêng tư của người tiêu dùng</td><td>Chịu bồi thường thiệt hại tinh thần, trường hợp nghiêm trọng truy cứu trách nhiệm hình sự</td></tr></tbody></table><h2 id="_5-to-chuc-nguoi-tieu-dung-va-giam-sat-xa-hoi" tabindex="-1">5. Tổ chức người tiêu dùng và giám sát xã hội <a class="header-anchor" href="#_5-to-chuc-nguoi-tieu-dung-va-giam-sat-xa-hoi" aria-label="Permalink to &quot;5. Tổ chức người tiêu dùng và giám sát xã hội&quot;">​</a></h2><p>Nhà nước khuyến khích, ủng hộ tất cả các tổ chức và cá nhân thực hiện giám sát xã hội đối với các hành vi gây thiệt hại cho quyền lợi hợp pháp của người tiêu dùng. Hội người tiêu dùng là tổ chức xã hội được thành lập theo pháp luật để thực hiện giám sát xã hội đối với hàng hóa và dịch vụ, bảo vệ quyền lợi hợp pháp của người tiêu dùng, và thực hiện các chức năng sau:</p><ol><li>Cung cấp thông tin tiêu dùng và dịch vụ tư vấn cho người tiêu dùng</li><li>Tham gia giám sát, kiểm tra hàng hóa và dịch vụ của cơ quan hành chính có liên quan</li><li>Phản ánh, tra cứu, đưa ra kiến nghị với cơ quan hành chính có liên quan về các vấn đề liên quan đến quyền lợi hợp pháp của người tiêu dùng</li><li>Tiếp nhận khiếu nại của người tiêu dùng, và điều tra, hòa giải các vấn đề được khiếu nại</li><li>Hỗ trợ người tiêu dùng bị thiệt hại khởi kiện đối với các hành vi gây thiệt hại cho quyền lợi hợp pháp của người tiêu dùng</li></ol><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>《Luật Bảo vệ Người tiêu dùng》 là người bảo vệ trật tự thị trường của văn minh cộng sinh neo. Bằng cách trao cho người tiêu dùng đầy đủ quyền, ràng buộc hành vi của nhà kinh doanh, và xây dựng cơ chế giải quyết tranh chấp đa dạng, nó đảm bảo giao dịch thị trường vận hành trên quỹ đạo công bằng, trung thực, cộng sinh, và ngăn chặn lĩnh vực thương mại trở thành mầm mống mới cho hành vi kiểu cướp đoạt.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>41-共生劳动法 (Luật Lao động Cộng sinh)</li><li>47-反垄断法 (Luật Chống độc quyền)</li><li>36-社会结构与阶层流动 (Cơ cấu xã hội và lưu động tầng lớp)</li></ul>',23)])])}const e=h(c,[["render",a]]);export{v as __pageData,e as default};
